W_OBST = 'Obstacle: %s Why it matters: %s Evidence: %s'


def why(o, m, e):
    return W_OBST % (o, m, e)


RAY_AB = gd({'A': (0, 0), 'B': (3, 1.2)}, [('ray', 'A', 'B')], h=150,
            desc='A ray that starts at point A, passes through point B, and continues past B (arrowhead beyond B).')
ANGLE_PQR = gd({'P': (3.2, 2.2), 'Q': (0, 0), 'R': (3.6, 0)}, [('ray', 'Q', 'P'), ('ray', 'Q', 'R'), ('ang', 'Q', 'R', 'P')], h=180,
               desc='Angle PQR: two rays start at point Q; one passes through P and the other through R. An arc marks the angle at Q.')
CROSS_RA = gd({'P': (0, 0)}, [('line', (-2, 0), (2, 0)), ('line', (0, -1.6), (0, 1.6)), ('ra', 'P', (1, 0), (0, 1)),
                              ('text', (2.3, 0.3), 'j'), ('text', (0.3, 1.9), 'k')], h=200, lab={'P': 'sw'},
              desc='Lines j and k cross at point P. A right-angle mark is drawn in one of the four angles at P.')

